package net.civeira.phylax.features.document.templatevariable.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.document.templatevariable.domain.TemplateVariable;
import net.civeira.phylax.features.document.templatevariable.domain.valueobject.EnabledVO;

@RequiredArgsConstructor
public class EnabledValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<EnabledVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @param enabled
   * @return
   */
  public T enabled(EnabledVO enabled) {
    this.value = Optional.of(enabled);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param enabled
   * @return
   */
  public T enabled(Optional<EnabledVO> enabled) {
    this.value = enabled;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param enabled
   * @return
   */
  public T enabled(Boolean enabled) {
    this.value = Optional.of(EnabledVO.from(enabled));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T enabledNull() {
    this.value = Optional.empty();
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<Boolean> getEnabled() {
    return value.map(EnabledVO::isEnabled);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<EnabledVO> getEnabledValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public EnabledVO readEnabled(final Optional<TemplateVariable> original,
      final ConstraintFailList fails) {
    return value
        .orElse(original.map(TemplateVariable::getEnabledValue).orElseGet(EnabledVO::nullValue));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetEnabled() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetEnabledIfMatches(final String field) {
    if ("enabled".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
